@RestController
class LocalHandlerController {

    @GetMapping("/orders/{id}")
    String getOrder(@PathVariable String id) {
        if (!id.equals("O1")) throw new OrderNotFoundException(id);
        return "Zamowienie: " + id;
    }

    @ExceptionHandler(OrderNotFoundException.class)
    ResponseEntity<String> handleNotFound(OrderNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ex.getMessage());
    }
}
// Handler dziala TYLKO dla wyjatkow rzuconych W TYM kontrolerze

@RestControllerAdvice
class GlobalExceptionHandler {

    @ExceptionHandler(PaymentDeclinedException.class)
    @ResponseStatus(HttpStatus.PAYMENT_REQUIRED)
    Map<String, String> handlePaymentDeclined(PaymentDeclinedException ex) {
        return Map.of("error", ex.getMessage());
    }
}
